import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        if (n > 40) {
            pw.println(0);
            pw.flush();
            return;
        }
        List<Point> pts = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            pts.add(new Point(sc.nextInt(), sc.nextInt(), sc.nextInt(), sc.nextInt(), sc.nextInt()));
        }
        if (n < 3) {
            pw.println(n);
            for (int i = 1; i <= n; i++) {
                pw.println(i);
            }
            pw.flush();
            return;
        }
        List<Integer> res = new ArrayList<>();
        for (int cIdx = 0; cIdx < n; cIdx++) {
            boolean isCenter = true;
            for (int aIdx = 0; aIdx < n; aIdx++) {
                if (aIdx == cIdx) continue;
                for (int bIdx = 0; bIdx < n; bIdx++) {
                    if (bIdx == cIdx || bIdx == aIdx) continue;
                    Point A = pts.get(aIdx).minus(pts.get(cIdx));
                    Point B = pts.get(bIdx).minus(pts.get(cIdx));
                    if (A.dot(B)) {
                        isCenter = false;
                        break;
                    }
                }
                if (!isCenter) break;
            }
            if (isCenter) res.add(cIdx + 1);
        }
        pw.println(res.size());
        for (int id : res) {
            pw.println(id);
        }
        pw.flush();
    }

    static class Point {
        long a, b, c, d, e;
        Point(long a, long b, long c, long d, long e) {
            this.a = a; this.b = b; this.c = c; this.d = d; this.e = e;
        }
        boolean dot(Point rhs) {
            return a * rhs.a + b * rhs.b + c * rhs.c + d * rhs.d + e * rhs.e > 0;
        }
        Point minus(Point rhs) {
            return new Point(a - rhs.a, b - rhs.b, c - rhs.c, d - rhs.d, e - rhs.e);
        }
    }
}
